namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateOnly LastInspected);

public interface IEquipmentService
{
    Task<List<EquipmentItem>> GetEquipmentAsync();
}

public class EquipmentService : IEquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A", "Warehouse 1", new DateOnly(2026, 5, 10)),
            new(2, "Conveyor Belt B", "Warehouse 2", new DateOnly(2026, 4, 22)),
            new(3, "CNC Lathe", "Machine Shop", new DateOnly(2026, 6, 1)),
            new(4, "Hydraulic Press", "Assembly Floor", new DateOnly(2026, 3, 15)),
            new(5, "Welding Robot", "Cell 3", new DateOnly(2026, 6, 20)),
            new(6, "Pallet Jack C", "Shipping Dock", new DateOnly(2026, 2, 28)),
            new(7, "Air Compressor", "Utility Room", new DateOnly(2025, 12, 5)),
            new(8, "Overhead Crane", "Bay 4", new DateOnly(2026, 1, 18)),
        };
    }
}

@page "/inventory"
@using InventoryApp.Services
@inject IEquipmentService EquipmentService
@attribute [StreamRendering]
@rendermode InteractiveServer

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;

    protected override async Task OnInitializedAsync()
    {
        items = await EquipmentService.GetEquipmentAsync();
    }
}

